    """The ops of an apply file, its placeholders numbered."""
    errors = []
    defined = []
    for i, ln in enumerate(text.split('\n'), 1):
        m = re.match(r'- ([FP])-\?(\d+) ', ln)
        if m:
            ph = '%s-?%s' % (m.group(1), m.group(2))
            if ph in defined:
                errors.append('line %d: %s is defined twice' % (i, ph))
